<template>
  <div class="relative h-full w-full overflow-hidden">
    <capacitor-google-map
      v-if="canRender"
      :id="mapId"
      ref="mapEl"
      class="block mt-0! h-full w-full"
    />

    <RouteMapFallback
      v-if="!canRender || state === 'error'"
      :stops="stops"
      :class="canRender ? 'absolute inset-0' : ''"
      @stop-tap="(seq: number) => emit('stop-tap', seq)"
    />
  </div>
</template>

<script setup lang="ts">
import { GoogleMap } from "@capacitor/google-maps";
import { Geolocation } from "@capacitor/geolocation";
import { Capacitor } from "@capacitor/core";
import RouteMapFallback from "./RouteMapFallback.vue";
import type { RouteMapStop } from "../route.types";

const props = defineProps<{ stops: RouteMapStop[] }>();
const emit = defineEmits<{ "stop-tap": [seq: number]; "map-double-tap": [] }>();

const apiKey = import.meta.env.VITE_GOOGLE_MAPS_API_KEY;
const canRender = !!apiKey;

const ALGIERS = { lat: 36.7538, lng: 3.0588 };

let instanceCount = 0;
const mapId = `presalio-route-map-${instanceCount++}`;

const mapEl = ref<HTMLElement | null>(null);
const state = ref<"loading" | "ready" | "error">("loading");
let map: GoogleMap | null = null;
let markerIds: string[] = [];

function geoPoints() {
  return props.stops.filter((s) => s.lat != null && s.lng != null);
}

async function waitForSize(el: HTMLElement, tries = 30): Promise<void> {
  for (let i = 0; i < tries; i++) {
    if (el.offsetHeight > 0 && el.offsetWidth > 0) return;
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
  }
}

async function renderStops() {
  if (!map) return;
  try {
    if (markerIds.length) {
      await map.removeMarkers(markerIds);
      markerIds = [];
    }
    const points = geoPoints();
    if (!points.length) return;

    markerIds = await map.addMarkers(
      points.map((s) => ({
        coordinate: { lat: s.lat, lng: s.lng },
        title: String(s.seq),
      })),
    );

    if (points.length > 1) {
      await map.addPolylines([
        {
          path: points.map((s) => ({ lat: s.lat, lng: s.lng })),
          strokeColor: "#1f6df5",
          strokeWeight: 4,
          strokeOpacity: 0.9,
        },
      ]);
    }
  } catch (error) {
    console.error("[RouteMap] renderStops failed", error);
  }
}

async function centerOnCurrentLocation() {
  if (!map) return;
  try {
    if (Capacitor.isNativePlatform()) {
      const status = await Geolocation.checkPermissions();
      if (status.location !== "granted" && status.coarseLocation !== "granted") {
        await Geolocation.requestPermissions();
      }
    }
    await map.enableCurrentLocation(true);
    const position = await Geolocation.getCurrentPosition({
      enableHighAccuracy: Capacitor.isNativePlatform(),
      timeout: 30000,
      maximumAge: 5000,
    });
    await map.setCamera({
      coordinate: {
        lat: position.coords.latitude,
        lng: position.coords.longitude,
      },
      zoom: 15,
      animate: true,
    });
  } catch (error) {
    console.error("[RouteMap] current location failed", error);
  }
}

onMounted(async () => {
  if (!canRender || !mapEl.value) {
    state.value = "error";
    return;
  }
  await nextTick();
  await waitForSize(mapEl.value);
  try {
    map = await GoogleMap.create({
      id: mapId,
      element: mapEl.value,
      apiKey: apiKey as string,
      config: { center: ALGIERS, zoom: 12, disableDefaultUI: true },
    });
    document.body.classList.add("capgmap-active");
    state.value = "ready";

    await renderStops();

    let lastMapTap = 0;
    await map.setOnMapClickListener(() => {
      const now = performance.now();
      if (now - lastMapTap < 320) {
        emit("map-double-tap");
        lastMapTap = 0;
      } else {
        lastMapTap = now;
      }
    });

    await map.setOnMarkerClickListener((event) => {
      const hit = props.stops.find(
        (s) =>
          s.lat != null &&
          s.lng != null &&
          Math.abs(s.lat - event.latitude) < 0.0001 &&
          Math.abs(s.lng - event.longitude) < 0.0001,
      );
      if (hit) emit("stop-tap", hit.seq);
    });
    await centerOnCurrentLocation();
  } catch (error) {
    console.error("[RouteMap] GoogleMap.create failed", error);
    state.value = "error";
  }
});

watch(
  () => props.stops,
  () => {
    if (state.value === "ready") void renderStops();
  },
  { deep: true },
);

onBeforeUnmount(async () => {
  document.body.classList.remove("capgmap-active");
  try {
    if (map) await map.destroy();
  } catch {
    void 0;
  }
});
</script>
