import { ROUTE_STATUS_META } from "./route.format";
import type { RouteStopStatus } from "./route.types";

export function partnerImageSrc(image: string | null): string | null {
  if (!image) return null;
  if (image.startsWith("data:") || image.startsWith("http") || image.startsWith("//")) {
    return image;
  }
  return `data:image/jpeg;base64,${image}`;
}

export function markerColorFor(status: RouteStopStatus): string {
  return ROUTE_STATUS_META[status].marker;
}

export interface FallbackPoint {
  x: number;
  y: number;
}

export function fallbackRoutePoints(count: number): FallbackPoint[] {
  if (count <= 0) return [];
  if (count === 1) return [{ x: 50, y: 34 }];
  const points: FallbackPoint[] = [];
  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    points.push({
      x: 10 + t * 80,
      y: 34 + Math.sin(t * Math.PI * 1.4 + 0.4) * 16,
    });
  }
  return points;
}

export function smoothPath(points: FallbackPoint[]): string {
  if (points.length < 2) return "";
  const d = [`M ${points[0]!.x} ${points[0]!.y}`];
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i === 0 ? 0 : i - 1]!;
    const p1 = points[i]!;
    const p2 = points[i + 1]!;
    const p3 = points[i + 2 < points.length ? i + 2 : i + 1]!;
    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;
    d.push(`C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2.x} ${p2.y}`);
  }
  return d.join(" ");
}
