import { sql } from "kysely";
import { rdb } from "@/shared/database";
import { useReactiveQuery } from "@/shared/composables/useReactiveQuery";
import { composeAddress, resolveStopStatus } from "../route.format";
import type { RouteItinerary, RouteStop, RouteMapStop } from "../route.types";

interface RouteRow {
  ruid: string;
  sequence: number;
  validationState: string | null;
  name: string;
  street: string | null;
  street2: string | null;
  zip: string | null;
  lat: number | null;
  lng: number | null;
  image: string | null;
}

interface RouteData {
  planningName: string | null;
  stops: RouteStop[];
}

async function getCurrentPlanning(): Promise<{ ruid: string; name: string } | null> {
  const planning = await rdb
    .selectFrom("planning_planning")
    .select(["_ruid", "name"])
    .where("_delete_date", "is", null)
    .orderBy(sql`case when state = 'open' then 0 else 1 end`)
    .orderBy("date_start", "desc")
    .limit(1)
    .executeTakeFirst();

  return planning ? { ruid: planning._ruid, name: planning.name } : null;
}

export function useRouteItinerary() {
  const searchTerm = ref("");

  const { data, loading } = useReactiveQuery<RouteData>(
    async () => {
      const planning = await getCurrentPlanning();
      if (!planning) return { planningName: null, stops: [] };

      const rows = await rdb
        .selectFrom("calendar_event as e")
        .innerJoin("res_partner as p", "p._ruid", "e.partner_customer_id")
        .select([
          "e._ruid as ruid",
          "e.sequence as sequence",
          "e.validation_state as validationState",
          "p.name as name",
          "p.street as street",
          "p.street2 as street2",
          "p.zip as zip",
          "p.partner_latitude as lat",
          "p.partner_longitude as lng",
          "p.image_1920 as image",
        ])
        .where("e.planning_id", "=", planning.ruid)
        .where("e._delete_date", "is", null)
        .where("p._delete_date", "is", null)
        .orderBy("e.sequence")
        .$castTo<RouteRow>()
        .execute();

      const stops: RouteStop[] = [];
      for (const row of rows) {
        const status = resolveStopStatus(row.validationState);
        if (status === "skipped") continue;
        stops.push({
          ruid: String(row.ruid),
          sequence: Number(row.sequence ?? 0),
          name: row.name,
          address: composeAddress(row.street, row.street2, row.zip),
          lat: row.lat ?? null,
          lng: row.lng ?? null,
          image: row.image ?? null,
          status,
          timeLabel: null,
        });
      }
      return { planningName: planning.name, stops };
    },
    {
      tables: ["planning_planning", "calendar_event", "res_partner", "real_date_range"],
      queryKey: "route:itinerary",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  const planningName = computed(() => data.value?.planningName ?? null);

  const matches = (stop: RouteStop, q: string) =>
    stop.name.toLowerCase().includes(q) || stop.address.toLowerCase().includes(q);

  const filtered = computed(() => {
    const all = data.value?.stops ?? [];
    const q = searchTerm.value.trim().toLowerCase();
    if (!q) return all;
    return all.filter((s) => matches(s, q));
  });

  const currentStop = computed<RouteStop | null>(() => {
    const first = filtered.value.find((s) => s.status === "upcoming");
    return first ? { ...first, status: "current" } : null;
  });

  const upcoming = computed<RouteStop[]>(() => {
    const pending = filtered.value.filter((s) => s.status === "upcoming");
    return pending.slice(1);
  });

  const completed = computed<RouteStop[]>(() =>
    filtered.value.filter((s) => s.status === "completed"),
  );

  const mapStops = computed<RouteMapStop[]>(() => {
    const currentRuid = currentStop.value?.ruid;
    return filtered.value
      .filter((s) => s.lat != null && s.lng != null)
      .map((s) => ({
        seq: s.sequence,
        name: s.name,
        lat: s.lat as number,
        lng: s.lng as number,
        status: s.ruid === currentRuid ? "current" : s.status,
      }));
  });

  const itinerary = computed<RouteItinerary>(() => ({
    currentStop: currentStop.value,
    upcoming: upcoming.value,
    completed: completed.value,
    mapStops: mapStops.value,
  }));

  const isEmpty = computed(() => !loading.value && filtered.value.length === 0);

  return { itinerary, planningName, searchTerm, loading, isEmpty };
}
